def G(t):
    R=[("Images 2.6","Імеджес два шість"),("ChatGPT","Чат Джі-Пі-Ті"),("Codex","Кодекс"),("Claude","Клод"),("Cursor","Курсор"),("Midjourney","Мідджорні"),("Grok","Грок"),("ElevenLabs","Ілевен Лабс"),("Higgsfield","Хіггсфілд"),
       ("Create with Gemini","Кріейт віз Джеміні"),("Customize","Кастомайз"),("Skills","Скілз"),("Create","Кріейт"),("Gemini","Джеміні"),("Google","Гугл"),("OpenAI","Оупен Ей-Ай"),("AI Studio","Ей-Ай Студіо"),
       ("gemini-2.5","джеміні два п'ять"),("2.5 Pro","два п'ять Про"),("2.5 Flash","два п'ять Флеш"),("Gemini 2.5","Gemini два п'ять"),("3.8 Flash","три вісім Флеш"),("3.5 Flash-Lite","три п'ять Флеш-Лайт"),("Omni 1.2","Omni один два"),("Flash-Lite","Флеш-Лайт"),("Flash","Флеш"),("Omni","Омні"),("Pro","Про"),("Plus","Плюс"),("Business","Бізнес"),("Instant","Інстант"),("API","Ей-Пі-Ай"),("GIF","гіф"),("TTS","ті-ті-ес"),
       ("tiktoken","тік-токен"),("thinking level","сінкінг левел"),("thought signature","тот сігнечер"),("function calling","фанкшн колінг"),("mono","моно"),("Reels","Рілз"),("TikTok","Тік-Ток"),("Shorts","Шортс")]
    for a,b in R: t=t.replace(a,b)
    t=re.sub(r"ШІ-(\w+)", r"\1 штучного інтелекту", t)
    for a,b in [("від ШІ","від штучного інтелекту"),("з ШІ","зі штучним інтелектом"),("на ШІ","на штучний інтелект"),("у ШІ","у штучний інтелект")]: t=t.replace(a,b)
    return t.replace("ШІ","штучний інтелект")

